mapper.select:
/* selectSellerMpClCatalogRecharterList */ SELECT X.* FROM ( SELECT A.RC_NO , A.RC_SEQ , A.REVISION , A.AGENT , A.BUYER ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = A.BUYER) AS BUYER_NM , A.BYIT_COMORG_CODE , A.BUYER_ITEM_NO , A.CONTRACT_NO , A.CONTRACT_SEQ , A.RC_TYPE , A.ATOB_DATE , A.ATOS_DATE , A.STOA_DATE , A.CLOSE_DATE , A.STOA_CLOSE_DATE , A.UNIT_PRICE , A.ATOB_UNIT_PRICE , A.LIST_PRICE , A.STOA_LIST_PRICE , A.A_NOTE , B.DESCRIPTION_LOC , B.SPECIFICATION , B.ORIGIN_CODE , (SELECT COD.TEXT2 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M001' AND CODE = B.ORIGIN_CODE) AS ORIGIN_NM , C.MAKER_NAME , C.UNIT_MEASURE , C.MAKER_PART_NO , C.MIN_ORDER_QTY , C.PUR_UNIT_QTY , A.CHANGE_USER_ID , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.CHANGE_USER_ID) USER_NM , (SELECT USR.PHONE_NUMBER FROM ICOMLUSR USR WHERE USR.USER_ID = A.CHANGE_USER_ID) USER_PHONE_NUMBER , NVL(D.RATE_GUBUN,'B') AS RATE_GUBUN , NVL(D.RATE, 3) AS RATE , A.LIST_PRICE_CHANGE_REASON FROM KEP_RCDT A, ICOMBYIT B, ICOMCQDT C, KEP_BUYER_RATE D WHERE A.BYIT_COMORG_CODE = B.BUYER AND A.BYIT_COMORG_CODE = C.BUYER AND B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = D.BUYER(+) AND A.AGENT = #{st_com_code} AND A.RC_TYPE = 'C' AND B.STATUS != 'D' AND C.STATUS != 'D' AND A.ATOB_DATE >= TO_CHAR(SYSDATE,'YYYYMMDD')
AND B.DESCRIPTION_LOC LIKE '%'||#{st_desc}||'%'
AND B.SPECIFICATION LIKE '%'||#{st_sepc}||'%'
AND C.MAKER_PART_NO LIKE '%'||#{st_maker_part_no}||'%'
)X WHERE 1=1
AND REPLACE(UPPER(X.BUYER_NM),' ','') LIKE '%'||UPPER(TRIM(REPLACE(#{st_buyer_name},' ','')))||'%'

mapper.update:

		/* saveSellerMpClCatalogRecharterList */
		 	UPDATE KEP_RCDT A                                   
               SET RC_TYPE =  'S'   
                   , S_NOTE = #{S_NOTE}
                   , CHANGE_DATE= SYSDATE
                   , STOA_DATE =TO_CHAR(SYSDATE, 'YYYYMMDD')
                   , STOA_USER_ID = #{st_user_id}
                   , UNIT_PRICE = #{UNIT_PRICE}
                   , ATOB_UNIT_PRICE = #{UNIT_PRICE}
                   , LIST_PRICE =#{STOA_LIST_PRICE}
                   , STOA_LIST_PRICE = #{STOA_LIST_PRICE}
                   , STOA_CLOSE_DATE = TO_CHAR(LAST_DAY(TO_DATE(#{STOA_CLOSE_DATE},'YYYYMMDD')),'YYYYMMDD')
                   , PRICE_RATE  = #{PRICE_RATE}
                   , LIST_PRICE_CHANGE_REASON = #{LIST_PRICE_CHANGE_REASON}
             WHERE A.RC_NO = #{RC_NO}
               AND A.RC_SEQ = #{RC_SEQ}
               AND A.REVISION = #{REVISION}    
               AND A.AGENT = #{AGENT}
               AND A.BUYER = #{BUYER}


		 /*rejectSellerMpClCatalogRecharter*/
		 	UPDATE KEP_RCDT A                                   
               SET RC_TYPE =  'G'   
                   , G_NOTE = #{CLOSE_STATUS_CODE}
                   , CHANGE_DATE= SYSDATE
                   , STOA_DATE =TO_CHAR(SYSDATE, 'YYYYMMDD')
                   , STOA_USER_ID = #{st_user_id}
             WHERE A.RC_NO = #{RC_NO}
               AND A.RC_SEQ = #{RC_SEQ}
               AND A.REVISION = #{REVISION}    
               AND A.AGENT = #{AGENT}
               AND A.BUYER = #{BUYER}


		 /*updateSellerMpClCatalogCloseFlag*/
		 	UPDATE ICOMBYIT A                                   
               SET A.PRODUCT_CLOSE_FLAG =  'Y'   
                   , A.CHANGE_DATE =TO_CHAR(SYSDATE, 'YYYYMMDD')
                   , A.CLOSE_STATUS_CODE = #{CLOSE_STATUS_CODE}
             WHERE A.BUYER = #{BYIT_COMORG_CODE}
               AND A.BUYER_ITEM_NO = #{BUYER_ITEM_NO}
